export function textureValueURL(value){try{const u=JSON.parse(atob(value)).textures.SKIN.url;const m=/^https?:\/\/textures\.minecraft\.net\/texture\/([a-f0-9]{32,64})$/.exec(u);if(m)return 'https://textures.minecraft.net/texture/'+m[1];}catch{}throw new Error('Minecraft TextureValue 또는 공식 텍스처 URL을 입력하세요.');}
export function normalizeTextureValue(value){const text=value.trim();if(/^https?:/.test(text)){const m=/^https?:\/\/textures\.minecraft\.net\/texture\/([a-f0-9]{32,64})$/.exec(text);if(!m)throw new Error('textures.minecraft.net의 텍스처 URL을 입력하세요.');return btoa(JSON.stringify({textures:{SKIN:{url:'https://textures.minecraft.net/texture/'+m[1]}}}));}textureValueURL(text);return text;}
export function headRef(node,state){const def=node.defaultTextureValue;const current=typeof def==='string'?{value:def}:def||{};if(current.paintTexture)return {skin:current.paintTexture,needsBake:true};if(current.value)return {value:current.value};if(node.paintTexture)return {skin:node.paintTexture,needsBake:true};const profile=state?.components?.['minecraft:profile']||state?.components?.profile;const props=profile?.properties;const value=node.tagHead?.Value||(Array.isArray(props)?props.find(p=>p.name==='textures')?.value:props?.textures?.[0]?.value||props?.textures?.[0]?.Value);return value?{value}:{};}
export function unbakedHeads(project){return project.objects.filter(o=>{if(o.virtual||o.block!=='minecraft:player_head'||!o.headSkin&&!o.headTexture&&!o.headNeedsBake)return false;if(o.headNeedsBake||!o.headTexture)return true;try{textureValueURL(o.headTexture);return false;}catch{return true;}});}
export async function bakeHeadSkin(skin,apiKey,{signal,onStatus=()=>{},fetcher=fetch,sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms))}={}){if(!apiKey?.trim())throw new Error('MineSkin API 키를 입력하세요.');const headers={'Content-Type':'application/json','Authorization':'Bearer '+apiKey.trim(),'MineSkin-User-Agent':'BDphysics/0.5.0'},request=async(url,options={})=>{const r=await fetcher(url,{...options,headers,signal});let data;try{data=await r.json();}catch{throw new Error('MineSkin 응답을 읽을 수 없습니다.');}if(!r.ok){const e=new Error(data.errors?.[0]?.message||'MineSkin 요청 실패 ('+r.status+')');e.retryAfter=Math.min(60000,Math.max(1000,Number(r.headers.get('retry-after')||3)*1000));e.status=r.status;throw e;}return data;};let data;for(let retry=0;retry<4;retry++){try{data=await request('https://api.mineskin.org/v2/queue',{method:'POST',body:JSON.stringify({url:skin,variant:'classic',visibility:'unlisted',name:'BDphysics head'})});break;}catch(e){if(e.status!==429||retry===3)throw e;onStatus('요청 대기 중');await sleep(e.retryAfter);}}const id=data.job?.id;if(!data.skin&&id){for(let i=0;i<150;i++){if(signal?.aborted)throw new DOMException('취소됨','AbortError');if(data.job?.status==='failed')throw new Error(data.errors?.[0]?.message||'텍스처 베이크 실패');onStatus(data.job?.status==='active'?'텍스처 베이크 중':'대기열 처리 중');await sleep(2000);try{data=await request('https://api.mineskin.org/v2/queue/'+encodeURIComponent(id));}catch(e){if(e.status===429){await sleep(e.retryAfter);continue;}throw e;}if(data.skin)break;}}const value=data.skin?.texture?.data?.value;if(!value)throw new Error('텍스처 처리가 끝나지 않았습니다. 잠시 뒤 다시 시도하세요.');textureValueURL(value);return {value,delay:Math.min(60000,Math.max(0,data.rateLimit?.next?.relative||0))};}

// After registration, preview the same texture reference that Minecraft receives.
// Keep drafts on their local PNG until conversion finishes.
export async function headItemModel(assets,o){
 if(o.headSkin&&(!o.headTexture||o.headNeedsBake))return assets.paintedHead(o.block,o.headSkin,o.itemDisplay,o.headSecondLayer!==false);
 if(o.headTexture)return assets.headItem(o.block,o.headTexture,o.itemDisplay,o.headSecondLayer!==false);
 return assets.item(o.block,o.itemDisplay);
}
